CREATE TABLE keywords(id INTEGER PRIMARY KEY, keyword TEXT NOT NULL UNIQUE, country TEXT NOT NULL, language TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE signals(id INTEGER PRIMARY KEY, keyword_id INTEGER NOT NULL, source TEXT NOT NULL, country TEXT NOT NULL, language TEXT NOT NULL, mention_count INTEGER NOT NULL, unique_authors INTEGER NOT NULL, engagement INTEGER NOT NULL, velocity_1h REAL NOT NULL, velocity_3h REAL NOT NULL, velocity_6h REAL NOT NULL, velocity_12h REAL NOT NULL, velocity_24h REAL NOT NULL, acceleration REAL NOT NULL, platform_count INTEGER NOT NULL, country_count INTEGER NOT NULL, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, is_fast_candidate INTEGER NOT NULL);
CREATE TABLE cost_metrics(id INTEGER PRIMARY KEY,component TEXT NOT NULL,provider TEXT NOT NULL,input_tokens INTEGER NOT NULL,output_tokens INTEGER NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL,captured_at TEXT NOT NULL,status TEXT NOT NULL);
